            modelBuilder.Entity("Scadex.Model.Entities.Connection", b =>
                {
                    b.Property<Guid>("Id")
                        .ValueGeneratedOnAdd()
                        .HasColumnType("uniqueidentifier");

                    b.Property<Guid>("CabinetId")
                        .HasColumnType("uniqueidentifier");

                    b.Property<string>("Color")
                        .IsRequired()
                        .HasColumnType("nvarchar(max)");

                    b.Property<DateTime?>("CreateDateUtc")
                        .HasColumnType("datetime2");

                    b.Property<string>("CreatedBy")
                        .HasColumnType("nvarchar(max)");

                    b.Property<string>("DeletedBy")
                        .HasColumnType("nvarchar(max)");

                    b.Property<DateTime?>("DeletedDateUtc")
                        .HasColumnType("datetime2");

                    b.Property<bool>("IsDeleted")
                        .HasColumnType("bit");

                    b.Property<string>("Label")
                        .HasColumnType("nvarchar(max)");

                    b.Property<int>("LineStyle")
                        .HasColumnType("int");

                    b.Property<int>("Routing")
                        .HasColumnType("int");

                    b.Property<Guid>("SourcePinId")
                        .HasColumnType("uniqueidentifier");

                    b.Property<double>("StrokeWidth")
                        .HasColumnType("float");

                    b.Property<Guid>("TargetPinId")
                        .HasColumnType("uniqueidentifier");

                    b.Property<DateTime?>("UpdateDateUtc")
                        .HasColumnType("datetime2");

                    b.Property<string>("UpdatedBy")
                        .HasColumnType("nvarchar(max)");

                    b.Property<string>("WaypointsJson")
                        .HasColumnType("nvarchar(max)");

                    b.Property<int>("WireType")
                        .HasColumnType("int");

                    b.Property<int>("ZIndex")
                        .HasColumnType("int");

                    b.HasKey("Id");

                    b.HasIndex("CabinetId");

                    b.HasIndex("TargetPinId");

                    b.HasIndex("SourcePinId", "TargetPinId")
                        .IsUnique()
                        .HasFilter("[IsDeleted] = 0");

                    b.ToTable("Connection", null, t =>
                        {
                            t.HasCheckConstraint("CK_Connection_DistinctPins", "[SourcePinId] <> [TargetPinId]");
                        });
                });

